package com.foodydelivery.tracker.config;
import java.util.*; import com.foodydelivery.tracker.auth.EmailAlreadyRegisteredException; import com.foodydelivery.tracker.auth.InvalidCredentialsException; import com.foodydelivery.tracker.order.InvalidOrderStatusTransitionException; import org.springframework.http.*; import org.springframework.web.bind.MethodArgumentNotValidException; import org.springframework.web.bind.annotation.*;
@RestControllerAdvice public class ApiExceptionHandler { @ExceptionHandler(NoSuchElementException.class) ResponseEntity<Map<String,String>> notFound(NoSuchElementException e){return ResponseEntity.status(HttpStatus.NOT_FOUND).body(Map.of("error",e.getMessage()));} @ExceptionHandler({InvalidOrderStatusTransitionException.class,EmailAlreadyRegisteredException.class}) ResponseEntity<Map<String,String>> conflict(RuntimeException e){return ResponseEntity.status(HttpStatus.CONFLICT).body(Map.of("error",e.getMessage()));} @ExceptionHandler(InvalidCredentialsException.class) ResponseEntity<Map<String,String>> unauthorized(InvalidCredentialsException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body(Map.of("error",e.getMessage()));} @ExceptionHandler(IllegalArgumentException.class) ResponseEntity<Map<String,String>> bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<Map<String,String>> validation(MethodArgumentNotValidException e){return ResponseEntity.badRequest().body(Map.of("error","Dados inválidos"));} }
